{
 "requirements": [
  {
   "id": "R1",
   "text": "Define the REST API specification (endpoints, payloads) for the attendance service."
  },
  {
   "id": "R2",
   "text": "Implement the face-registration endpoint that stores a student's face embedding."
  },
  {
   "id": "R3",
   "text": "Implement the attendance-marking endpoint that matches a camera frame against registered faces."
  },
  {
   "id": "R4",
   "text": "Compare at least two open-source face-recognition libraries and choose one."
  },
  {
   "id": "R5",
   "text": "Build a web dashboard for teachers showing attendance per lecture."
  },
  {
   "id": "R6",
   "text": "Export attendance reports as CSV."
  },
  {
   "id": "R7",
   "text": "Integration tests covering every endpoint."
  },
  {
   "id": "R8",
   "text": "User manual for teachers."
  },
  {
   "id": "R9",
   "text": "A privacy note explaining how biometric data is stored and deleted, based on current data-protection guidance."
  },
  {
   "id": "R10",
   "text": "Load test showing the marking endpoint handles 100 requests per second."
  }
 ],
 "constraints": [
  "Python backend",
  "open-source libraries only"
 ],
 "deliverables": [
  "source repository",
  "user manual",
  "privacy note",
  "test and load-test report"
 ],
 "notes": "The face library must be chosen (R4) before registration (R2) is built. The dashboard (R5) consumes the API defined in R1. Attendance marking (R3) needs faces registered by R2. The privacy note (R9) needs research on data-protection guidance first."
}

